    /** @param  array<string, mixed>  $config  Credential and endpoint settings. @return array{success: bool, message?: string, error?: string} */
    public function testConnection(array $config): array
    {
        $accessToken = (string) ($config['access_token'] ?? '');
        $baseUrl = rtrim((string) ($config['base_url'] ?? 'https://graph.microsoft.com/v1.0'), '/');
        if ($accessToken === '') { return ['success' => false, 'error' => 'Provide a Microsoft Graph access token.']; }

        try {
            $response = Http::withHeaders(['Accept' => 'application/json', 'Authorization' => 'Bearer ' . $accessToken])->timeout(10)->get($baseUrl . '/sites/root');
            if (!$response->successful()) { return ['success' => false, 'error' => 'Microsoft Graph returned HTTP ' . $response->status() . '.']; }
            return ['success' => true, 'message' => 'Connected to Microsoft SharePoint through Microsoft Graph.'];
        } catch (\Throwable $e) {
            return ['success' => false, 'error' => $e->getMessage()];
        }
    }

