        $account = $context['account'] ?? null;
        if ($account !== null) {
            $creds = app(CredentialResolver::class);
            return new MicrosoftSharePointService(accessToken: $creds->get('microsoft-sharepoint', 'access_token', '', $account), baseUrl: $creds->get('microsoft-sharepoint', 'base_url', 'https://graph.microsoft.com/v1.0', $account));
        }

        return app(MicrosoftSharePointService::class);
    }

    public function scriptDocsPath(): ?string { return __DIR__ . '/../script-docs/microsoft-sharepoint.md'; }
    public function isIntegration(): bool { return true; }
}
